        APIQuery.append(&_query, "from", from)
        APIQuery.append(&_query, "to", to)
        APIQuery.append(&_query, "project", project)
        APIQuery.append(&_query, "ticket", ticket)
        APIQuery.append(&_query, "chat", chat)
        APIQuery.append(&_query, "epic", epic)
        return APIRequest(
            method: "GET", template: "/costs",
            path: "/api/v1/costs",
